import{H as e,V as t,et as n,j as r}from"./chunks/framework.ChZHrXbO.js";var i=JSON.parse(`{"title":"MySQL管理","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/mysql-administration.md","filePath":"mysql/mysql-administration.md"}`),a={name:`mysql/mysql-administration.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="mysql管理" tabindex="-1">MySQL管理 <a class="header-anchor" href="#mysql管理" aria-label="Permalink to “MySQL管理”">​</a></h1><h2 id="_1-系统数据库" tabindex="-1">1.系统数据库 <a class="header-anchor" href="#_1-系统数据库" aria-label="Permalink to “1.系统数据库”">​</a></h2><p>Mysql数据库安装完成后，自带了四个数据库，具体作用如下：</p><table tabindex="0"><thead><tr><th>数据库</th><th>含义</th></tr></thead><tbody><tr><td>mysql</td><td>存储MVSQL服务器正常运行所需要的各种信息(时区、主从、用户、权限等)</td></tr><tr><td>information_schema</td><td>提供了访问数据库元数据的各种表和视图，包含数据库、表、字段类型及访问权限等</td></tr><tr><td>performance_schema</td><td>为MySQL服务器运行时状态提供了一个底层监控功能，主要用于收集数据库服务器性能参数</td></tr><tr><td>sys</td><td>包含了一系列方便 DBA和开发人员利用 performance_schema性能数据库进行性能调优和诊断的视图</td></tr></tbody></table><h2 id="_2-常用工具" tabindex="-1">2.常用工具 <a class="header-anchor" href="#_2-常用工具" aria-label="Permalink to “2.常用工具”">​</a></h2><h3 id="_2-1-mysql" tabindex="-1">2.1 mysql <a class="header-anchor" href="#_2-1-mysql" aria-label="Permalink to “2.1 mysql”">​</a></h3><p>该mysql不是指mysql服务，而是指mysql的客户端工具</p><div class="language-Properties"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">Properties</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mysql [options] [database]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">options选项:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-u[username]|--</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">user</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=username : 指定用户名，如-uroot</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-p[password]|--password[=password] : 指定用户密码，如-p123456</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-h[host]|--</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=host : 指定服务器IP或域名，如-h127.0.0.1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-P[port]|--</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=port : 指定连接端口（P为大写），如-P3306</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-e[execute]|</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">execute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=execute : 在客户端执行SQL语句并退出（无需进入mysql系统），但前面要跟上操作的数据库名，SQL用双引号包裹，如mysql -uroot -p123456 mysql -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;select * from user&quot;</span></span></code></pre></div><h3 id="_2-2-mysqladmin" tabindex="-1">2.2 mysqladmin <a class="header-anchor" href="#_2-2-mysqladmin" aria-label="Permalink to “2.2 mysqladmin”">​</a></h3><p>mysqladmin是一个执行管理操作的客户端程序，可以用它来检查服务器的配置和当前运行状态，创建并删除数据库等</p><div class="language-Properties"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">Properties</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">## 通过帮助文档查看选项：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mysqladmin --help</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">示例选项:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">create dbname : 创建指定数据库，如mysqladmin -uroot -p123456 create text</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">drop dbname : 删除指定数据库，如mysqladmin -uroot -p123456 drop text</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ping : 检查MySQL服务器是否正在运行，如mysqladmin -uroot -p123456 ping</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">status : 查看服务器状态，如mysqladmin -uroot -p123456 status</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">shutdown : 关闭MySQL服务器，如mysqladmin -uroot -p123456 shutdown</span></span></code></pre></div><h3 id="_2-3-mysqlbinlog" tabindex="-1">2.3 mysqlbinlog <a class="header-anchor" href="#_2-3-mysqlbinlog" aria-label="Permalink to “2.3 mysqlbinlog”">​</a></h3><p>由于服务器生成的二进制文件以二进制格式保存，所以如果想要检查这些文本的文本格式，就会使用到mysqlbinlog日志管理工具（需要管理员身份）</p><div class="language-Properties"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">Properties</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mysqlbinlog [options] log-files1 log-files2 ...</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mysqlbinlog log-file</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">options选项:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-d dbname|--</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">database</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=dbname : 指定数据库名称，只列出指定的数据库相关操作，如mysqlbinlog -d mysql binlog.000001</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-o n|--</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">offset</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=n : 忽略日志中的前n行数据，如mysqlbinlog -o 10 binlog.000001</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-r filename|--</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">result-file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=filename : 将输出的文本日志格式写到目标文件filename中,filename可以用绝对路径，如</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mysqlbinlog -s binlog.000001 -r </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;F:\\login.000001&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-s|--short-form : 让输出内容更简洁，只输出必要的信息，如mysqlbinlog -s mysql binlog.000001</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--start-datetime : 读取指定开始时间之后的事件，如mysqlbinlog --</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">start-datetime</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2025-03-18 10:00:00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> binlog.000001</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--stop-datetime : 读取指定结束时间之前的时间，如mysqlbinlog --</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">stop-datetime</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2025-03-18 12:00:00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> binlog.000001</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--start-position : 指定从二进制日志的哪个位置开始读取事件,如mysqlbinlog --</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">start-position</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=100 binlog.000001</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--stop-position : 指定读取二进制日志时的结束位置，如mysqlbinlog --</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">stop-position</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=200 binlog.000001</span></span></code></pre></div><ul><li>在使用mysqlbinlog之前，需要先定位到binlog.000001所在文件夹，否则后面的使用要用到绝对路径或相对路径</li></ul><h3 id="_2-4-mysqlshow" tabindex="-1">2.4 mysqlshow <a class="header-anchor" href="#_2-4-mysqlshow" aria-label="Permalink to “2.4 mysqlshow”">​</a></h3><p>客户端对象查找工具，用来很快地查看存在哪些数据库、数据库中的表、表中的列和或者索引</p><div class="language-Properties"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">Properties</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mysqlshow [options] [db_name [table_name [col_name]]]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">options选项:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--count : 显示数据库及表的统计信息（数据库、表均可以不指定）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-i : 显示指定数据库或者指定表的状态信息</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">示例:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">## 查询每个数据库的表的数量及表中记录的数量</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mysqlshow -uroot -p123456 --count</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">## 查询mysql库中每个表中的字段数及行数</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mysqlshow -uroot -p123456 mysql --count</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">## 查询mysql库中user表的详细信息</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mysqlshow -uroot -p123456 mysql user --count</span></span></code></pre></div><h3 id="_2-5-mysqldump" tabindex="-1">2.5 mysqldump <a class="header-anchor" href="#_2-5-mysqldump" aria-label="Permalink to “2.5 mysqldump”">​</a></h3><p>mysqldump客户端工具用来备份数据库或在不同数据库之间进行数据迁移。备份内容包含创建表、及插入表的SQL语句</p><div class="language-Properties"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">Properties</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">## 目标文件filename.sql可以用绝对路径或相对路径</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mysqldump [options] db_name[tables] &gt; filename.sql                </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">##备份指定数据库中的部分或全部表到目标文件</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mysqldump [options] --database|-B db1 [db2 db3 ...] &gt; filename.sql                </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">##备份多个指定的数据库到目标文件</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mysqldump [options] --all-databases|-A &gt; filename.sql                </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">##备份 MySQL 服务器上的所有数据库到目标文件</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">options连接选项:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-u[username]|--</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">user</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=username : 指定用户名</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-p[password]|--password[=password] : 指定用户密码，如-p123456</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-h[host]|--</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=host : 指定服务器IP或域名，如-h127.0.0.1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-P[port]|--</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=port : 指定连接端口（P为大写），如-P3306</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">options输出选项:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--add-drop-database : 在每个数据库创建语句前加上drop database语句</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--add-drop-table : 在每个表创建语句前加上drop table语句，默认开启，不开启（--skip-add-drop-table）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-n|--no-create-db : 不包含数据库的创建语句</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-t|--no-create-info : 不包含数据表的创建语句</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-d|--no-data : 不包含数据</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-T filename|--tab[=filename] : 自动生成两个文件，一个.sql文件，创建表结构的语句，一个.txt文件，数据文件,例如：</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">## 拷贝mysql数据库下的user表</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mysqldump -u root -p --</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">tab</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/path/to/export/directory mysql user 或</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mysqldump -u root -p -T /path/to/export/directory mysql user</span></span></code></pre></div><p><strong>-T filename|--tab[=filename]参数</strong>：</p><ul><li><p>生成的两个文件文件名和表名一致</p></li><li><p>filename指文件存放路径，可以是绝对路径，也可以是相对路径，如果当前已定位到指定路径，可以不指定filename</p></li><li><p>-T后必须跟filename，而--tab后可以不跟filename</p></li></ul><h3 id="_2-6-mysqlimport-source" tabindex="-1">2.6 mysqlimport/source <a class="header-anchor" href="#_2-6-mysqlimport-source" aria-label="Permalink to “2.6 mysqlimport/source”">​</a></h3><p>mysqlimport是客户端数据导入工具，用来导入mysqldump加-T参数后导出的文本文件</p><div class="language-Properties"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">Properties</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mysqlimport [options] db_name textfile1 [textfile2 ...]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">示例：mysqlimport -uroot -p text /tmp/city.txt</span></span></code></pre></div><p>如果需要导入sql文件，可以使用mysql中的source命令</p><div class="language-Properties"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">Properties</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">## filename.sql可以使用路径</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">source filename.sql</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">;</span></span></code></pre></div>`,28)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};